INSERT INTO `wp_options` VALUES ('256','_elementor_pro_free_trial_data','a:2:{s:7:\"timeout\";i:1782653145;s:5:\"value\";s:575:\"[{\"status\":\"inactive\",\"heading\":\"You\\u2019ve come this far. Why stop here?\",\"subheading\":\"Elementor Pro Free Trial\",\"introduction\":\"Take your site beyond the basics with a free 7-day Elementor Pro trial with no strings attached:\",\"listItems\":[\"100+ widgets\",\"Theme Builder\",\"Advanced design controls\",\"Custom CSS for pixel-perfect sites - and more\"],\"ctaText\":\"Unlock my free trial\",\"ctaUrl\":\"https:\\/\\/go.elementor.com\\/go-pro-free-trial-popup\\/\",\"secondaryAction\":\"Not now\",\"image\":\"https:\\/\\/assets.elementor.com\\/pro-free-trial-popup\\/v1\\/images\\/free_trial_banner.png\"}]\";}','off');
